import{_ as o,o as a,c as e,ag as r}from"./chunks/framework.CAXxHpAX.js";const c=JSON.parse('{"title":"如何教育子女","description":"","frontmatter":{},"headers":[],"relativePath":"20-专题研究/topic-亲子教育.md","filePath":"20-专题研究/topic-亲子教育.md","lastUpdated":1778040484000}'),l={name:"20-专题研究/topic-亲子教育.md"};function u(h,t,d,q,i,n){return a(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="如何教育子女" tabindex="-1">如何教育子女 <a class="header-anchor" href="#如何教育子女" aria-label="Permalink to &quot;如何教育子女&quot;">​</a></h1><blockquote><p>专题分析：亲子关系中的修行智慧 组合模型：圆融中和 + 自然务实 + 历境炼心</p></blockquote><hr><h2 id="一、了空居士的亲子教育观" tabindex="-1">一、了空居士的亲子教育观 <a class="header-anchor" href="#一、了空居士的亲子教育观" aria-label="Permalink to &quot;一、了空居士的亲子教育观&quot;">​</a></h2><p>了空居士的亲子教育理念根植于&quot;家庭是道场&quot;的观念，他特别强调<strong>身教重于言教</strong>：</p><blockquote><p><strong>&quot;自古以来的圣贤教化别人都是一个办法，就是身教为先，也就是所谓的身教重于言教。譬如我叫儿子这么做，我们必须自己也这么做。……上梁不正了下梁自然就会歪。&quot;</strong></p></blockquote><p>— 处世系列（亲子教育答疑）</p><hr><h2 id="二、亲子教育的三大原则" tabindex="-1">二、亲子教育的三大原则 <a class="header-anchor" href="#二、亲子教育的三大原则" aria-label="Permalink to &quot;二、亲子教育的三大原则&quot;">​</a></h2><h3 id="原则一-身教为先——你在做的-比你说的更有力" tabindex="-1">原则一：身教为先——你在做的，比你说的更有力 <a class="header-anchor" href="#原则一-身教为先——你在做的-比你说的更有力" aria-label="Permalink to &quot;原则一：身教为先——你在做的，比你说的更有力&quot;">​</a></h3><blockquote><p><strong>&quot;家庭是道场，工作单位是道场，社会是道场。怎么去对待家庭？怎么去对待社会？就在日常生活中。&quot;</strong></p></blockquote><p>— <a href="/60-原文段落/金刚经1分-修行在生活中">金刚经1分-修行在生活中</a></p><p>孩子不是听你说的，是看你做的。你对长辈的态度→孩子对你的态度。你对邻居的善意→孩子对同学的善意。你在家的言行→孩子的行为模板。</p><h3 id="原则二-因材施教——没有固定的教育方法" tabindex="-1">原则二：因材施教——没有固定的教育方法 <a class="header-anchor" href="#原则二-因材施教——没有固定的教育方法" aria-label="Permalink to &quot;原则二：因材施教——没有固定的教育方法&quot;">​</a></h3><blockquote><p><strong>&quot;无有定法名阿耨多罗三藐三菩提，亦无有定法如来可说。&quot;</strong></p></blockquote><p>— <a href="/60-原文段落/金刚经7分-无有定法">金刚经7分-无有定法</a></p><p>每个孩子不一样——有的要鼓励，有的要适当施压。每个年龄不一样——小孩讲道理，大孩讲尊重。</p><blockquote><p><strong>&quot;经验不能照搬，你的孩子和别人不一样。&quot;</strong></p></blockquote><p>— <a href="/60-原文段落/道德经64章-经验不能教条主义">道德经64章-经验不能教条主义</a></p><h3 id="原则三-共同成长——教育孩子就是历境炼心" tabindex="-1">原则三：共同成长——教育孩子就是历境炼心 <a class="header-anchor" href="#原则三-共同成长——教育孩子就是历境炼心" aria-label="Permalink to &quot;原则三：共同成长——教育孩子就是历境炼心&quot;">​</a></h3><blockquote><p><strong>&quot;烦恼即菩提。一切烦恼为如来种。&quot;</strong></p></blockquote><p>— <a href="/60-原文段落/金刚经5分-烦恼即菩提">金刚经5分-烦恼即菩提</a></p><p>孩子的每一个&quot;问题行为&quot;都是父母修行的题目：孩子不听话→考验耐心；孩子撒谎→考验智慧；孩子叛逆→考验包容。</p><hr><h2 id="三、常见教育误区" tabindex="-1">三、常见教育误区 <a class="header-anchor" href="#三、常见教育误区" aria-label="Permalink to &quot;三、常见教育误区&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误区</th><th>正解</th><th>原文依据</th></tr></thead><tbody><tr><td>孩子必须考第一名</td><td>尽力就好，&quot;因上精进，果上随缘&quot;</td><td><a href="/60-原文段落/道德经14章-因上精进果上随缘">道德经14章-因上精进果上随缘</a></td></tr><tr><td>打骂才有效</td><td>打骂是无力感，不是教育</td><td>—</td></tr><tr><td>要为孩子铺好一切路</td><td>不经历风雨的孩子长不大</td><td>—</td></tr><tr><td>我说了孩子就该听</td><td>身教重于言教——&quot;上梁不正下梁歪&quot;</td><td>处世系列</td></tr></tbody></table><hr><h2 id="四、当孩子让你生气时" tabindex="-1">四、当孩子让你生气时 <a class="header-anchor" href="#四、当孩子让你生气时" aria-label="Permalink to &quot;四、当孩子让你生气时&quot;">​</a></h2><blockquote><p><strong>&quot;不平静时问自己：&#39;我为什么要不平静？这样正确吗？&#39;&quot;</strong></p></blockquote><p>— <a href="/60-原文段落/金刚经5分-保持平静的要诀">金刚经5分-保持平静的要诀</a></p><blockquote><p><strong>&quot;不怕念起，只怕觉迟。&quot;</strong> 觉察到自己在生气，已经是进步。</p></blockquote><p>— <a href="/60-原文段落/答疑2021-不怕念起只怕觉迟">答疑2021-不怕念起只怕觉迟</a></p><hr><h2 id="五、了空居士原话" tabindex="-1">五、了空居士原话 <a class="header-anchor" href="#五、了空居士原话" aria-label="Permalink to &quot;五、了空居士原话&quot;">​</a></h2><blockquote><p><strong>&quot;身教为先，身教重于言教。上梁不正了下梁自然就会歪。&quot;</strong></p></blockquote><p>— 处世系列</p><blockquote><p><strong>&quot;因上精进，果上随缘。&quot;</strong></p></blockquote><p>— <a href="/60-原文段落/道德经14章-因上精进果上随缘">道德经14章-因上精进果上随缘</a></p><blockquote><p><strong>&quot;经验不能照搬，你的孩子和别人不一样。&quot;</strong></p></blockquote><p>— <a href="/60-原文段落/道德经64章-经验不能教条主义">道德经64章-经验不能教条主义</a></p><blockquote><p><strong>&quot;家庭是道场。怎么去对待家庭？就在日常生活中。&quot;</strong></p></blockquote><p>— <a href="/60-原文段落/金刚经1分-修行在生活中">金刚经1分-修行在生活中</a></p><hr><h2 id="六、推荐模型" tabindex="-1">六、推荐模型 <a class="header-anchor" href="#六、推荐模型" aria-label="Permalink to &quot;六、推荐模型&quot;">​</a></h2><ul><li><a href="/10-核心模型/model-圆融中和">圆融中和</a> — 不偏不倚的教育态度</li><li><a href="/10-核心模型/model-自然务实">自然务实</a> — 抓住教育核心，不搞花架子</li><li><a href="/10-核心模型/model-历境炼心">历境炼心</a> — 教育孩子即修行</li></ul><h2 id="相关概念" tabindex="-1">相关概念 <a class="header-anchor" href="#相关概念" aria-label="Permalink to &quot;相关概念&quot;">​</a></h2><ul><li><a href="/50-概念资料/dict-家庭道场">dict-家庭道场</a> — 家庭是教育的第一现场</li><li><a href="/50-概念资料/dict-敬">dict-敬</a> — 尊重孩子与尊重自己</li></ul><hr><blockquote><p>创建日期：2026-05-06 | 修订：2026-05-07（删除无法验证出处的引文，以&quot;身教重于言教&quot;为唯一核心原话；全部原话添加原文段落链接；新增常见误区表） 来源：处世系列（亲子教育答疑）、金刚经第1分、第7分</p></blockquote>',49)])])}const s=o(l,[["render",u]]);export{c as __pageData,s as default};
